"""Plan and stage one narrowly scoped NFS server configuration; never activate it.

The CLI defaults to a read-only plan. Future --apply stages directories/config
only, requires root and the current reviewed plan digest, and makes a backup
first. Package installation, exportfs and systemd activation are separate actions.
"""

import argparse
from datetime import datetime, timezone
import hashlib
import fcntl
import ipaddress
import json
import os
from pathlib import Path
import pwd
import grp
import re
import stat
import subprocess
import tempfile
import uuid

SHARED = "/srv/ml-shared"
OBJECTS = SHARED + "/objects"
STAGING = SHARED + "/.publish"
MARKER = SHARED + "/.nfs-setup.json"
EXPORTS = "/etc/exports.d/distributed-ml.exports"
BACKUPS = "/var/backups/distributed-ml-nfs"
HEADER = "# Managed by distributed-dl-system nfs-server v1\n"
CONFIG_FILE = Path(__file__).resolve().parents[1] / "config/nfs-server.json"
MAX_BYTES = 256 * 1024
LOCAL_FILESYSTEMS = {"ext4", "ext3", "ext2", "xfs", "btrfs", "f2fs", "overlay", "tmpfs"}


class SetupError(ValueError):
    """A proposed setup cannot be safely interpreted or applied."""


def encoded(value):
    return (json.dumps(value, sort_keys=True, separators=(",", ":")) + "\n").encode()


def digest(value):
    return hashlib.sha256(encoded(value)).hexdigest()


def _unique(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise SetupError("Duplicate configuration field: " + key)
        result[key] = value
    return result


def address(value):
    if type(value) is not str:
        raise SetupError("Clients/server must be literal IPv4 host addresses")
    try:
        ip = ipaddress.IPv4Address(value)
    except ipaddress.AddressValueError as error:
        raise SetupError("Clients/server must be literal IPv4 host addresses") from error
    if ip.is_loopback or ip.is_multicast or ip.is_unspecified or ip.is_link_local or ip.is_reserved or int(ip) == 0xffffffff:
        raise SetupError("Use a routable, explicitly reviewed IPv4 host address")
    return str(ip)


def selected_nodes(config):
    """Default to all three; a smaller deployment requires an explicit selection."""
    nodes = config.get("deployment_nodes", ["pi01", "pi02", "pi03"])
    if not isinstance(nodes, list) or not nodes or any(type(node) is not str or node not in {"pi01", "pi02", "pi03"} for node in nodes) or len(nodes) != len(set(nodes)):
        raise SetupError("deployment_nodes must be a nonempty unique list of known Pi IDs")
    return sorted(nodes)


def validate_config(value):
    fields = {"schema_version", "server_address", "clients", "publisher_uid", "publisher_gid", "layout"}
    if not isinstance(value, dict) or set(value) not in (fields, fields | {"deployment_nodes"}) or type(value["schema_version"]) is not int or value["schema_version"] != 1:
        raise SetupError("Expected exactly the version-one NFS server configuration fields")
    selected_nodes(value)
    address(value["server_address"])
    clients = value["clients"]
    if not isinstance(clients, dict) or set(clients) != {"pi01", "pi02", "pi03"}:
        raise SetupError("Explicitly list pi01, pi02 and pi03; unknown addresses must be null")
    known = [address(ip) for ip in clients.values() if ip is not None]
    if len(set(known)) != len(known) or value["server_address"] in known:
        raise SetupError("Client addresses must be distinct and different from the server")
    for field in ("publisher_uid", "publisher_gid"):
        number = value[field]
        if number is not None and (type(number) is not int or not 1 <= number < 2**31):
            raise SetupError(field + " must be an existing dedicated non-root identity, or null")
    if value["layout"] not in ("subdirectory", "dedicated-filesystem"):
        raise SetupError("layout must be subdirectory or dedicated-filesystem")
    return value


def load_config(path):
    with Path(path).open("rb") as stream:
        raw = stream.read(MAX_BYTES + 1)
    if len(raw) > MAX_BYTES:
        raise SetupError("NFS server configuration is too large")
    return validate_config(json.loads(raw.decode("utf-8"), object_pairs_hook=_unique))


def options(layout):
    if layout == "dedicated-filesystem":
        return "ro,sync,root_squash,no_subtree_check,mountpoint,secure,sec=sys"
    return "ro,sync,root_squash,subtree_check,secure,sec=sys"


def render_exports(config):
    entries = [ip + "(" + options(config["layout"]) + ")"
               for node, ip in sorted(config["clients"].items()) if node in selected_nodes(config) and ip is not None]
    return HEADER + (OBJECTS + " " + " ".join(entries) + "\n" if entries else "")


def check_exports(text, *, managed=False):
    """Conservative syntax/policy checker, not the complete nfs-utils grammar.

    Unmanaged tables may contain comments only: refuse, never reinterpret or
    activate existing unrelated exports. Managed rows allow only this exact root,
    literal hosts and fixed safe options. Unknown syntax is a review blocker.
    """
    if managed and not text.startswith(HEADER):
        raise SetupError("Existing managed filename lacks our ownership marker")
    rows = [line.strip() for line in text.splitlines() if line.strip() and not line.lstrip().startswith("#")]
    if not managed:
        if rows:
            raise SetupError("Unmanaged noncomment exports require separate syntax/policy review")
        return []
    if len(rows) > 1:
        raise SetupError("Managed export must contain exactly one input-only export row")
    clients = []
    for line in rows:
        parts = line.split()
        if not parts or parts[0] != OBJECTS or len(parts) < 2:
            raise SetupError("Only the dedicated immutable objects path may be exported")
        for part in parts[1:]:
            match = re.fullmatch(r"([0-9.]+)\(([^()]*)\)", part)
            if not match or match[2] not in (options("subdirectory"), options("dedicated-filesystem")):
                raise SetupError("Malformed or unsafe export client/options")
            clients.append(address(match[1]))
    if len(set(clients)) != len(clients):
        raise SetupError("Duplicate export client")
    return clients


def check_active_table(text, config):
    """Accept only this export's reviewed literal clients and safe known defaults."""
    allowed = set(options(config["layout"]).split(",")) | {
        "wdelay", "hide", "nocrossmnt", "no_all_squash", "secure_locks", "acl",
        "no_pnfs", "anonuid=65534", "anongid=65534",
    }
    expected_clients = {config["clients"][node] for node in selected_nodes(config) if config["clients"][node] is not None}
    for line in text.splitlines():
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        parts = line.split()
        if len(parts) < 2 or parts[0] != OBJECTS:
            raise SetupError("Unexpected existing active export path")
        for client in parts[1:]:
            match = re.fullmatch(r"([0-9.]+)\(([^()]*)\)", client)
            if not match or address(match[1]) not in expected_clients:
                raise SetupError("Unexpected active export client")
            values = set(match[2].split(","))
            if not set(options(config["layout"]).split(",")) <= values or not values <= allowed:
                raise SetupError("Active export options require separate review")


class Host:
    """All paths are fixed logical host paths; tests use an isolated fake root."""

    def __init__(self, root=Path("/"), admin_uid=0):
        self.root = Path(root)
        self.admin_uid = admin_uid

    def path(self, logical):
        return self.root / logical.lstrip("/")

    def facts(self):
        def run(args):
            result = subprocess.run(args, capture_output=True, text=True, timeout=5)
            if result.returncode:
                raise SetupError("Read-only prerequisite query failed: " + " ".join(args))
            return result.stdout
        packages = {}
        for name in ("nfs-kernel-server", "nfs-common"):
            result = subprocess.run(["dpkg-query", "-W", "-f=${Status}", name], capture_output=True, text=True, timeout=5)
            packages[name] = result.returncode == 0 and result.stdout == "install ok installed"
        interfaces = json.loads(run(["ip", "-j", "address", "show"]))
        addresses = sorted(a["local"] for i in interfaces for a in i.get("addr_info", []) if a.get("family") == "inet")
        mounts = []
        for line in Path("/proc/self/mountinfo").read_text().splitlines():
            left, right = line.split(" - ", 1)
            a, b = left.split(), right.split()
            target = re.sub(r"\\([0-7]{3})", lambda m: chr(int(m[1], 8)), a[4])
            mounts.append({"target": target, "root": a[3], "device": a[2], "fstype": b[0]})
        return {"packages": packages, "addresses": addresses, "mounts": mounts}

    def metadata(self, logical, mounts):
        path = self.path(logical)
        for parent in [*reversed(path.relative_to(self.root).parents), path.relative_to(self.root)]:
            logical_parent = "/" if parent == Path(".") else "/" + parent.as_posix()
            matches = [m for m in mounts if logical_parent == m["target"] or logical_parent.startswith(m["target"].rstrip("/") + "/")]
            if matches and max(matches, key=lambda m: len(m["target"]))["fstype"] not in LOCAL_FILESYSTEMS:
                raise SetupError("Refusing remote/automount/unknown filesystem traversal: " + logical)
            actual = self.root / parent
            try:
                info = actual.lstat()
            except FileNotFoundError:
                return None
            if stat.S_ISLNK(info.st_mode):
                raise SetupError("Symlink in host setup path: " + str(actual))
            if actual != path and (not stat.S_ISDIR(info.st_mode) or info.st_uid != self.admin_uid or info.st_mode & 0o022):
                raise SetupError("Host setup ancestor is not a protected admin directory: " + str(actual))
        return {"uid": info.st_uid, "gid": info.st_gid, "mode": stat.S_IMODE(info.st_mode),
                "directory": stat.S_ISDIR(info.st_mode), "regular": stat.S_ISREG(info.st_mode)}

    def read(self, logical, mounts):
        info = self.metadata(logical, mounts)
        if info is None:
            return None
        if not info["regular"]:
            raise SetupError("Expected a regular administrative file: " + logical)
        with self.path(logical).open("rb") as stream:
            raw = stream.read(MAX_BYTES + 1)
        if len(raw) > MAX_BYTES:
            raise SetupError("Administrative file exceeds inspection bound: " + logical)
        return {"text": raw.decode("utf-8"), **info, "sha256": hashlib.sha256(raw).hexdigest()}


def build_plan(config, host=None):
    config = validate_config(config)
    host = host or Host()
    facts = host.facts()
    blockers = []
    admin_directories = {}
    for name in ("/srv", "/etc", "/var/backups", BACKUPS):
        info = host.metadata(name, facts["mounts"])
        admin_directories[name] = info
        if info and (not info["directory"] or info["uid"] != host.admin_uid or info["mode"] & 0o022):
            raise SetupError("Unprotected administrative directory: " + name)
        if info is None and name != BACKUPS:
            blockers.append("Required administrative parent directory missing: " + name)
    for node, ip in config["clients"].items():
        if node in selected_nodes(config) and ip is None:
            blockers.append(node + ": verified client address missing; never broaden the allowlist to compensate")
    if config["server_address"] not in facts["addresses"]:
        blockers.append("Proposed server address is not currently assigned to this controller")
    for name, installed in facts["packages"].items():
        if not installed:
            blockers.append(name + " missing: package provisioning needs separate approval; script never installs it")
    for name in ("publisher_uid", "publisher_gid"):
        if config[name] is None:
            blockers.append(name + " missing: review/preprovision the dedicated trusted publisher identity")
    if host.root == Path("/") and config["publisher_uid"] is not None and config["publisher_gid"] is not None:
        try:
            pwd.getpwuid(config["publisher_uid"])
            grp.getgrgid(config["publisher_gid"])
        except KeyError:
            blockers.append("Publisher UID/GID must already exist; no account creation is performed")
    files = {}
    names = ["/etc/exports", EXPORTS]
    directory = host.metadata("/etc/exports.d", facts["mounts"])
    if directory:
        if not directory["directory"] or directory["uid"] != host.admin_uid or directory["mode"] & 0o022:
            raise SetupError("exports.d must be a protected admin directory")
        candidates = sorted(p.name for p in host.path("/etc/exports.d").iterdir() if p.name.endswith(".exports") and not p.name.startswith("."))
        if len(candidates) > 32:
            raise SetupError("Too many export tables for this bounded preparer")
        names += ["/etc/exports.d/" + name for name in candidates]
    for name in sorted(set(names)):
        record = host.read(name, facts["mounts"])
        files[name] = record
        if record:
            if record["uid"] != host.admin_uid or record["mode"] & 0o022:
                raise SetupError("Export configuration must be admin-owned and not group/world writable")
            check_exports(record["text"], managed=name == EXPORTS)
    # Read the managed export table directly; do not invoke exportfs for inspection.
    etab = host.read("/var/lib/nfs/etab", facts["mounts"])
    if etab:
        if etab["uid"] != host.admin_uid or etab["mode"] & 0o022:
            raise SetupError("Active export table must be protected admin-owned metadata")
        check_active_table(etab["text"], config)
    dirs = {name: host.metadata(name, facts["mounts"]) for name in (SHARED, OBJECTS, STAGING)}
    marker = host.read(MARKER, facts["mounts"])
    expected_marker = {"version": 1, "objects": OBJECTS, "publisher_uid": config["publisher_uid"], "publisher_gid": config["publisher_gid"]}
    if marker:
        if marker["uid"] != host.admin_uid or marker["mode"] != 0o600 or json.loads(marker["text"]) != expected_marker:
            raise SetupError("Existing setup marker differs; never change publisher ownership automatically")
    elif dirs[SHARED] and any(host.path(SHARED).iterdir()):
        raise SetupError("Refusing to adopt nonempty unmarked /srv/ml-shared")
    expected = {SHARED: (host.admin_uid, None, 0o755), OBJECTS: (config["publisher_uid"], config["publisher_gid"], 0o755), STAGING: (config["publisher_uid"], config["publisher_gid"], 0o700)}
    for name, current in dirs.items():
        uid, gid, mode = expected[name]
        if current and (not current["directory"] or current["mode"] != mode or (uid is not None and current["uid"] != uid) or (gid is not None and current["gid"] != gid)):
            raise SetupError("Existing directory attributes differ; no chown/chmod of existing data: " + name)
    mount = next((m for m in facts["mounts"] if m["target"] == OBJECTS), None)
    parent_mounts = [m for m in facts["mounts"] if SHARED == m["target"] or SHARED.startswith(m["target"].rstrip("/") + "/")]
    parent_mount = max(parent_mounts, key=lambda m: len(m["target"])) if parent_mounts else None
    if config["layout"] == "dedicated-filesystem" and not (mount and mount["root"] == "/" and parent_mount and mount["device"] != parent_mount["device"]):
        blockers.append("no_subtree_check requires a mounted whole dedicated filesystem, not a bind/empty directory")
    desired = render_exports(config)
    check_exports(desired, managed=True)
    observed = {"facts": facts, "config_files": files, "active_table": etab, "directories": dirs,
                "marker": marker, "exports_directory": directory, "admin_directories": admin_directories}
    plan = {"version": 1, "config": config, "desired_exports": desired, "observed": observed,
            "blockers": blockers, "apply_ready": not blockers, "mode": "dry-run",
            "scope": "Stage configuration only; never install packages, activate exports or change services",
            "proposed_directories": [
                {"path": SHARED, "uid": host.admin_uid, "gid": "admin primary group", "mode": "0755"},
                {"path": OBJECTS, "uid": config["publisher_uid"], "gid": config["publisher_gid"], "mode": "0755"},
                {"path": STAGING, "uid": config["publisher_uid"], "gid": config["publisher_gid"], "mode": "0700"}],
            "config_file_to_stage": EXPORTS, "existing_data_policy": "Verify existing attributes; never recurse, delete or change them",
            "package_command_for_separate_review_only": ["apt-get", "--no-download", "install", "nfs-kernel-server", "nfs-common"],
            "activation_after_separate_approval": ["systemctl start nfs-server.service", "exportfs -ra"],
            "backup_before_changes": BACKUPS, "syntax_check": "Conservative managed grammar; unmanaged files must be comments/empty. Native exportfs not invoked."}
    plan["plan_sha256"] = digest(plan)
    return plan


def _write_new(path, raw, mode, uid, gid):
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, mode)
    with os.fdopen(fd, "wb") as stream:
        stream.write(raw)
        stream.flush()
        os.fchmod(stream.fileno(), mode)
        os.fchown(stream.fileno(), uid, gid)
        os.fsync(stream.fileno())


def _sync(path):
    fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def stage_configuration(config, reviewed_sha256, host=None):
    """Future root-only configuration staging. Never call without user approval.

    A matching digest binds review to current facts; it is not itself permission.
    Failures leave backups and any new directories intact, without activating NFS.
    """
    host = host or Host()
    if os.geteuid() != host.admin_uid:
        raise SetupError("Configuration staging requires the host administrator")
    plan = build_plan(config, host)
    if reviewed_sha256 != plan["plan_sha256"]:
        raise SetupError("Current plan differs from reviewed digest; review a fresh dry-run")
    if plan["blockers"]:
        raise SetupError("Cannot stage configuration: " + "; ".join(plan["blockers"]))
    current = plan["observed"]["config_files"][EXPORTS]
    if current and current["text"] == plan["desired_exports"] and plan["observed"]["marker"] and all(plan["observed"]["directories"].values()):
        return {"status": "no_changes", "activated": False}
    # Only future explicitly approved staging creates this private lock. Dry-runs
    # do not create it. Protected /etc and no-follow prevent untrusted lock paths.
    lock = host.path("/etc/.distributed-ml-nfs.lock")
    fd = os.open(lock, os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
    try:
        info = os.fstat(fd)
        if not stat.S_ISREG(info.st_mode) or info.st_uid != host.admin_uid or stat.S_IMODE(info.st_mode) != 0o600 or info.st_nlink != 1:
            raise SetupError("Unprotected NFS setup lock")
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        fresh = build_plan(config, host)
        if fresh["plan_sha256"] != reviewed_sha256 or fresh["blockers"]:
            raise SetupError("Controller changed while obtaining setup lock; review again")
        return _stage_reviewed(fresh, host)
    finally:
        os.close(fd)


def _stage_reviewed(plan, host):
    config = plan["config"]
    state = plan["observed"]
    mounts = state["facts"]["mounts"]
    # Check all administrative ancestors before any creation. No recursive fixups.
    for name in ("/srv", "/etc", "/var/backups", BACKUPS):
        info = host.metadata(name, mounts)
        if info and (not info["directory"] or info["uid"] != host.admin_uid or info["mode"] & 0o022):
            raise SetupError("Unprotected administrative directory: " + name)
    backup_root = host.path(BACKUPS)
    backup_root.mkdir(mode=0o700, exist_ok=True)
    _sync(backup_root.parent)
    backup = backup_root / (datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ") + "-" + uuid.uuid4().hex)
    backup.mkdir(mode=0o700)
    record = {"reviewed_plan_sha256": plan["plan_sha256"], "files": state["config_files"],
              "installed_exports_sha256": hashlib.sha256(plan["desired_exports"].encode()).hexdigest(),
              "restore_scope": "Restore only the managed drop-in after hash/ownership checks; other exports were never modified. Preserve all input/staging directories."}
    _write_new(backup / "before.json", encoded(record), 0o600, host.admin_uid, os.getegid())
    _sync(backup)
    _sync(backup_root)
    def create_directory(name, uid, gid, mode):
        if not host.path(name).exists():
            host.path(name).mkdir(mode=mode)
            os.chown(host.path(name), uid, gid)
            os.chmod(host.path(name), mode)
            _sync(host.path(name).parent)
    create_directory(SHARED, host.admin_uid, os.getegid(), 0o755)
    if state["marker"] is None:
        marker = {"version": 1, "objects": OBJECTS, "publisher_uid": config["publisher_uid"], "publisher_gid": config["publisher_gid"]}
        _write_new(host.path(MARKER), encoded(marker), 0o600, host.admin_uid, os.getegid())
        _sync(host.path(SHARED))
    # The marker precedes child directories, so interrupted setup can be safely
    # resumed without adopting an unmarked nonempty directory.
    create_directory(OBJECTS, config["publisher_uid"], config["publisher_gid"], 0o755)
    create_directory(STAGING, config["publisher_uid"], config["publisher_gid"], 0o700)
    host.path("/etc/exports.d").mkdir(mode=0o755, exist_ok=True)
    _sync(host.path("/etc"))
    fd, temporary = tempfile.mkstemp(prefix=".distributed-ml-", dir=host.path("/etc/exports.d"))
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(plan["desired_exports"].encode())
            stream.flush()
            os.fchmod(stream.fileno(), 0o644)
            os.fchown(stream.fileno(), host.admin_uid, os.getegid())
            os.fsync(stream.fileno())
        if host.read(EXPORTS, mounts) != state["config_files"][EXPORTS]:
            raise SetupError("Managed config changed before publication; preserving it")
        if state["config_files"][EXPORTS] is None:
            os.link(temporary, host.path(EXPORTS), follow_symlinks=False)
        else:
            os.replace(temporary, host.path(EXPORTS))
        _sync(host.path("/etc/exports.d"))
    finally:
        Path(temporary).unlink(missing_ok=True)
    return {"status": "configuration_staged_not_activated", "backup": str(backup), "activated": False}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", type=Path, default=CONFIG_FILE)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--dry-run", action="store_true", help="Read-only plan (also the default)")
    mode.add_argument("--apply", action="store_true", help="Future approved root-only config staging; never activates NFS")
    parser.add_argument("--reviewed-plan-sha256", help="Required with --apply, after explicit approval")
    args = parser.parse_args(argv)
    try:
        config = load_config(args.config)
        if args.apply:
            if not args.reviewed_plan_sha256:
                raise SetupError("--apply requires a current --reviewed-plan-sha256 and prior user approval")
            result = stage_configuration(config, args.reviewed_plan_sha256)
        else:
            if args.reviewed_plan_sha256:
                raise SetupError("Review digest is only used with --apply")
            result = build_plan(config)
        print(json.dumps(result, indent=2, sort_keys=True))
        return 2 if result.get("blockers") else 0
    except (SetupError, OSError, ValueError, subprocess.SubprocessError) as error:
        parser.exit(2, "NFS server setup refused: " + str(error) + "\n")


if __name__ == "__main__":
    raise SystemExit(main())

nfs_client.py.source:
"""Prepare boot-independent NFS client units; default is an offline selected-Pi plan.

--inspect-local requires an explicit node and only reads local state. Future
approved administrator actions provision a missing package or stage config;
neither enables units, activates mounts, edits fstab or alters the legacy agent.
"""

import argparse
from datetime import datetime, timezone
import fcntl
import hashlib
import json
import os
from pathlib import Path
import shutil
import stat
import subprocess
import uuid

from .nfs_mount import INPUTS, EXPORT, parse_mountinfo, unescape
from .nfs_server import Host, SetupError, MAX_BYTES, address, digest, encoded, selected_nodes, _unique, _write_new, _sync

CONFIG_FILE = Path(__file__).resolve().parents[1] / "config/nfs-clients.json"
ROOT = "/srv/mlnfs"
MARKER = ROOT + "/.nfs-client-setup.json"
LIBEXEC = "/usr/local/libexec/distributed-ml"
GUARD = LIBEXEC + "/nfs_mount.py"
MOUNT = "srv-mlnfs-inputs.mount"
AUTOMOUNT = "srv-mlnfs-inputs.automount"
READY = "ml-nfs-ready.service"
UNITS = "/etc/systemd/system"
BACKUPS = "/var/backups/distributed-ml-nfs-client"
LOCK = "/etc/.distributed-ml-nfs-client.lock"
HEADER = "# Managed by distributed-dl-system nfs-client v1\n"
MOUNT_OPTIONS = "ro,nosuid,nodev,noexec,hard,vers=4.1,proto=tcp,sec=sys,resvport,timeo=50,retrans=2,retry=0,nofail"
PACKAGE_COMMAND = ["/usr/bin/apt-get", "--no-download", "--no-remove", "--assume-yes", "install", "nfs-common"]
QUERY_ENV = {"PATH": "/usr/sbin:/usr/bin:/sbin:/bin", "LC_ALL": "C"}


def validate_config(config):
    fields = {"schema_version", "server_address", "clients"}
    if not isinstance(config, dict) or set(config) not in (fields, fields | {"deployment_nodes"}) or type(config["schema_version"]) is not int or config["schema_version"] != 1:
        raise SetupError("Expected exactly version-one NFS client fields")
    selected_nodes(config)
    address(config["server_address"])
    clients = config["clients"]
    if not isinstance(clients, dict) or set(clients) != {"pi01", "pi02", "pi03"}:
        raise SetupError("List all three Pis, with null for unknown LAN addresses")
    known = [address(value) for value in clients.values() if value is not None]
    if len(known) != len(set(known)) or config["server_address"] in known:
        raise SetupError("Clients must be distinct and different from the controller")
    return config


def load_config(path):
    with Path(path).open("rb") as stream:
        raw = stream.read(MAX_BYTES + 1)
    if len(raw) > MAX_BYTES:
        raise SetupError("Client proposal is too large")
    return validate_config(json.loads(raw.decode(), object_pairs_hook=_unique))


def source(config):
    return config["server_address"] + ":" + EXPORT


def render_files(config, node):
    validate_config(config)
    if node not in selected_nodes(config):
        raise SetupError("Selected Pi is excluded from this deployment")
    mount = HEADER + "\n".join([
        "[Unit]", "Description=Distributed ML trusted input mount (" + node + ")",
        "[Mount]", "What=" + source(config), "Where=" + INPUTS, "Type=nfs",
        "Options=" + MOUNT_OPTIONS, "TimeoutSec=15s", "DirectoryMode=0700", ""])
    automount = HEADER + "\n".join([
        "[Unit]", "Description=Distributed ML on-demand input automount (" + node + ")",
        "[Automount]", "Where=" + INPUTS, "DirectoryMode=0700", "TimeoutIdleSec=0",
        "[Install]", "WantedBy=multi-user.target", ""])
    ready = HEADER + "\n".join([
        "[Unit]", "Description=Distributed ML input mount admission (" + node + ")",
        "Requires=" + MOUNT, "After=" + MOUNT,
        "[Service]", "Type=oneshot", "User=root", "Group=root", "UMask=0077",
        "ExecStart=/usr/bin/python3 -I " + GUARD + " --source " + source(config),
        "NoNewPrivileges=yes", "ProtectSystem=strict", "ProtectHome=yes", "PrivateTmp=yes",
        "TimeoutStartSec=5s", ""])
    guard = HEADER + Path(__file__).with_name("nfs_mount.py").read_text()
    return {UNITS + "/" + MOUNT: mount, UNITS + "/" + AUTOMOUNT: automount,
            UNITS + "/" + READY: ready, GUARD: guard}


def plan_all(config):
    validate_config(config)
    nodes = selected_nodes(config)
    blockers = [node + ": verified LAN address missing; deployment remains deferred"
                for node in nodes if config["clients"][node] is None]
    return {"version": 1, "mode": "offline-three-client-preview" if len(nodes) == 3 else "offline-selected-client-preview", "config": config,
            "apply_ready": False, "blockers": blockers + ["Fresh local inspection on each Pi and explicit 2.4 approval required"],
            "clients": {node: {"address": config["clients"][node], "files": render_files(config, node)} for node in nodes},
            "package_if_missing_after_approval": PACKAGE_COMMAND,
            "activation_after_separate_approval": ["systemctl daemon-reload", "systemctl enable --now " + AUTOMOUNT],
            "fstab_policy": "Never written; existing mount and agent units unchanged",
            "runtime_enablement": "Blocked until authorization, job isolation and supervised staging are implemented"}


class ClientHost(Host):
    def facts(self):
        result = subprocess.run(["dpkg-query", "-W", "-f=${Status}", "nfs-common"], capture_output=True, text=True, timeout=5, env=QUERY_ENV)
        installed = result.returncode == 0 and result.stdout == "install ok installed"
        result = subprocess.run(["ip", "-j", "address", "show"], capture_output=True, text=True, timeout=5, env=QUERY_ENV)
        if result.returncode:
            raise SetupError("Local read-only interface query failed")
        interfaces = json.loads(result.stdout)
        mounts = parse_mountinfo(Path("/proc/self/mountinfo").read_text())
        return {"nfs_common_installed": installed, "mount_helper_available": shutil.which("mount.nfs", path=QUERY_ENV["PATH"]) is not None,
                "addresses": sorted(a["local"] for interface in interfaces for a in interface.get("addr_info", []) if a.get("family") == "inet"),
                "mounts": mounts}


def inspect_local(config, node, host=None):
    validate_config(config)
    if node not in selected_nodes(config):
        raise SetupError("Selected Pi is excluded from this deployment")
    host = host or ClientHost()
    facts = host.facts()
    mounts = facts["mounts"]
    blockers = [name + ": verified LAN address missing" for name in selected_nodes(config) if config["clients"][name] is None]
    if config["clients"][node] not in facts["addresses"]:
        blockers.append("Selected Pi LAN address is not assigned to this host; never apply on the controller")
    if not facts["nfs_common_installed"]:
        blockers.append("nfs-common missing; separate approved offline package provisioning required")
    elif not facts["mount_helper_available"]:
        blockers.append("mount.nfs missing despite installed nfs-common; repair requires review")
    files = render_files(config, node)
    observed = {"facts": facts, "files": {}, "directories": {}}
    for name in ("/srv", "/etc", UNITS, "/var/backups", "/usr/local", "/usr/local/libexec", LIBEXEC, BACKUPS):
        current = host.metadata(name, mounts)
        observed["directories"][name] = current
        if current and (not current["directory"] or current["uid"] != host.admin_uid or current["mode"] & 0o022):
            raise SetupError("Unprotected administrative directory: " + name)
        if current is None and name in ("/srv", "/etc", UNITS, "/var/backups", "/usr/local"):
            blockers.append("Required administrative parent missing: " + name)
    fstab = host.read("/etc/fstab", mounts)
    observed["fstab"] = fstab
    if fstab:
        if fstab["uid"] != host.admin_uid or fstab["mode"] & 0o022:
            raise SetupError("Unprotected fstab; never overwrite it")
        for line in fstab["text"].splitlines():
            if not line.strip() or line.lstrip().startswith("#"):
                continue
            fields = line.split()
            if len(fields) < 4:
                raise SetupError("Malformed existing fstab requires manual review")
            target = unescape(fields[1])
            if target == ROOT or target.startswith(ROOT + "/"):
                raise SetupError("Conflicting fstab input path; preserve it for manual review")
    # Never stat/traverse mounted input paths, including an autofs trigger.
    occupied = any(m["target"] == ROOT or m["target"].startswith(ROOT + "/") for m in mounts)
    if occupied:
        raise SetupError("Managed input path is already mounted; drain and review before configuration staging")
    for name, mode in ((ROOT, 0o700), (INPUTS, 0o700)):
        current = host.metadata(name, mounts)
        observed["directories"][name] = current
        if current and (not current["directory"] or current["uid"] != host.admin_uid or current["mode"] != mode):
            raise SetupError("Input path must be a protected admin-owned 0700 directory")
    marker = host.read(MARKER, mounts)
    expected_marker = {"version": 1, "node": node, "source": source(config)}
    observed["marker"] = marker
    if marker:
        if marker["uid"] != host.admin_uid or marker["mode"] != 0o600 or json.loads(marker["text"]) != expected_marker:
            raise SetupError("Client setup marker differs; never silently repurpose a mount root")
    elif observed["directories"][ROOT] and any(host.path(ROOT).iterdir()):
        raise SetupError("Refusing nonempty unmarked input root")
    if observed["directories"][INPUTS] and any(host.path(INPUTS).iterdir()):
        raise SetupError("Underlying input mountpoint must be empty; preserve its data")
    for unit in (MOUNT, AUTOMOUNT, READY):
        for base in (UNITS, "/run/systemd/system", "/usr/lib/systemd/system"):
            if host.metadata(base + "/" + unit + ".d", mounts) is not None:
                raise SetupError("Existing unit override requires manual review: " + unit)
            if base != UNITS and host.metadata(base + "/" + unit, mounts) is not None:
                raise SetupError("Existing runtime/vendor unit requires manual review: " + unit)
    for target in ("multi-user.target.wants", "remote-fs.target.wants", "local-fs.target.wants"):
        if host.metadata(UNITS + "/" + target + "/" + MOUNT, mounts) is not None:
            raise SetupError("Direct boot dependency on input mount requires manual review")
    for name in files:
        record = host.read(name, mounts)
        observed["files"][name] = record
        if record and (record["uid"] != host.admin_uid or record["mode"] != 0o644 or not record["text"].startswith(HEADER)):
            raise SetupError("Unowned/unsafe client configuration target: " + name)
    plan = {"version": 1, "mode": "local-read-only-plan", "node": node, "config": config,
            "files": files, "observed": observed, "blockers": blockers, "apply_ready": not blockers,
            "package_if_missing_after_approval": PACKAGE_COMMAND, "backup_before_changes": BACKUPS,
            "scope": "Stage only; never edit fstab, mount, enable/reload units or restart the legacy agent"}
    plan["plan_sha256"] = digest(plan)
    return plan


def _review(config, node, sha, host):
    if os.geteuid() != host.admin_uid:
        raise SetupError("Live client action requires the host administrator and separate approval")
    plan = inspect_local(config, node, host)
    if plan["plan_sha256"] != sha:
        raise SetupError("Local plan changed; review a fresh digest")
    return plan


def provision_package(config, node, sha, host=None):
    """Future explicitly approved offline provisioning; package scripts may affect services."""
    host = host or ClientHost()
    plan = _review(config, node, sha, host)
    if plan["observed"]["facts"]["nfs_common_installed"]:
        return {"status": "package_already_installed", "command_executed": False}
    if any(not blocker.startswith("nfs-common missing;") for blocker in plan["blockers"]):
        raise SetupError("Resolve non-package blockers before offline provisioning")
    result = subprocess.run(PACKAGE_COMMAND, check=True, env={"PATH": "/usr/sbin:/usr/bin:/sbin:/bin", "DEBIAN_FRONTEND": "noninteractive"})
    return {"status": "package_command_completed_review_new_plan", "returncode": result.returncode,
            "command_executed": True, "warning": "Package maintainer scripts may change services; unit staging/activation not performed"}


def stage_configuration(config, node, sha, host=None):
    host = host or ClientHost()
    plan = _review(config, node, sha, host)
    if plan["blockers"]:
        raise SetupError("Client configuration blocked: " + "; ".join(plan["blockers"]))
    state = plan["observed"]
    if state["marker"] and all(state["directories"].get(name) for name in (ROOT, INPUTS, LIBEXEC)) and all(state["files"][name] and state["files"][name]["text"] == text for name, text in plan["files"].items()):
        return {"status": "no_changes", "activated": False}
    fd = os.open(host.path(LOCK), os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
    try:
        info = os.fstat(fd)
        if not stat.S_ISREG(info.st_mode) or info.st_uid != host.admin_uid or stat.S_IMODE(info.st_mode) != 0o600 or info.st_nlink != 1:
            raise SetupError("Unprotected client setup lock")
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        fresh = _review(config, node, sha, host)
        return _stage(fresh, host)
    finally:
        os.close(fd)


def _stage(plan, host):
    state = plan["observed"]
    mounts = state["facts"]["mounts"]
    backup_root = host.path(BACKUPS)
    backup_root.mkdir(mode=0o700, exist_ok=True)
    _sync(backup_root.parent)
    backup = backup_root / (datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ") + "-" + uuid.uuid4().hex)
    backup.mkdir(mode=0o700)
    journal = {"plan_sha256": plan["plan_sha256"], "node": plan["node"], "files": state["files"],
               "fstab_unchanged": state["fstab"],
               "installed_sha256": {name: hashlib.sha256(text.encode()).hexdigest() for name, text in plan["files"].items()},
               "restore_scope": "Only listed managed files after current hash checks; preserve data, fstab, unrelated units and backups"}
    _write_new(backup / "before.json", encoded(journal), 0o600, host.admin_uid, os.getegid())
    _sync(backup)
    _sync(backup_root)
    def directory(name, mode):
        if not host.path(name).exists():
            host.path(name).mkdir(mode=mode)
            os.chmod(host.path(name), mode)
            _sync(host.path(name).parent)
    directory(ROOT, 0o700)
    if state["marker"] is None:
        _write_new(host.path(MARKER), encoded({"version": 1, "node": plan["node"], "source": source(plan["config"])}), 0o600, host.admin_uid, os.getegid())
        _sync(host.path(ROOT))
    directory(INPUTS, 0o700)
    directory("/usr/local/libexec", 0o755)
    directory(LIBEXEC, 0o755)
    for name, text in plan["files"].items():
        if state["files"][name] and state["files"][name]["text"] == text:
            continue
        path = host.path(name)
        temporary = path.parent / (".ml-nfs-client-" + uuid.uuid4().hex)
        try:
            _write_new(temporary, text.encode(), 0o644, host.admin_uid, os.getegid())
            if host.read(name, mounts) != state["files"][name]:
                raise SetupError("Client config changed before publication; preserve it: " + name)
            if state["files"][name] is None:
                os.link(temporary, path, follow_symlinks=False)
            else:
                os.replace(temporary, path)
            _sync(path.parent)
        finally:
            temporary.unlink(missing_ok=True)
    return {"status": "configuration_staged_not_activated", "backup": str(backup), "activated": False}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", type=Path, default=CONFIG_FILE)
    parser.add_argument("--node", choices=("pi01", "pi02", "pi03"))
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--dry-run", action="store_true", help="Offline preview for selected Pis (all three by default)")
    mode.add_argument("--inspect-local", action="store_true", help="Read-only inspection on the selected Pi")
    mode.add_argument("--apply", action="store_true", help="Future approved root-only config staging, no activation")
    mode.add_argument("--install-missing-package", action="store_true", help="Future separately approved root-only offline package provisioning")
    parser.add_argument("--reviewed-plan-sha256")
    args = parser.parse_args(argv)
    try:
        config = load_config(args.config)
        local = args.inspect_local or args.apply or args.install_missing_package
        if local and not args.node:
            raise SetupError("Local inspection/actions require an explicit --node")
        if not local and args.node:
            raise SetupError("Offline preview covers the configured deployment nodes; omit --node")
        if args.apply or args.install_missing_package:
            if not args.reviewed_plan_sha256:
                raise SetupError("Live action requires a current reviewed digest and prior explicit approval")
            action = stage_configuration if args.apply else provision_package
            result = action(config, args.node, args.reviewed_plan_sha256)
        else:
            if args.reviewed_plan_sha256:
                raise SetupError("Review digest is only used for approved live actions")
            result = inspect_local(config, args.node) if local else plan_all(config)
        print(json.dumps(result, indent=2, sort_keys=True))
        return 2 if result.get("blockers") else 0
    except (SetupError, OSError, ValueError, subprocess.SubprocessError) as error:
        parser.exit(2, "NFS client setup refused: " + str(error) + "\n")


if __name__ == "__main__":
    raise SystemExit(main())

nfs_mount.py.source:
"""Read-only NFS mount admission check, also installable as a standalone guard.

This reads kernel metadata only: it never looks up a file in the mount, triggers
an automount, stages inputs or authorizes/launches training. The future trusted
stager must use the check in its own mount namespace before accessing inputs.
"""

import argparse
import ipaddress
import json
from pathlib import Path
import re

INPUTS = "/srv/mlnfs/inputs"
EXPORT = "/srv/ml-shared/objects"
REQUIRED = {"ro", "nosuid", "nodev", "noexec", "hard", "proto=tcp", "sec=sys", "vers=4.1"}
FORBIDDEN = {"rw", "soft", "softerr", "softreval", "suid", "dev", "exec", "user", "users"}


class MountNotReady(ValueError):
    """The visible mount metadata does not meet the reviewed input contract."""


def unescape(value):
    return re.sub(r"\\([0-7]{3})", lambda match: chr(int(match[1], 8)), value)


def parse_mountinfo(text):
    mounts = []
    for line in text.splitlines():
        if not line:
            continue
        try:
            left, right = line.split(" - ", 1)
            a, b = left.split(), right.split()
            mounts.append({"id": int(a[0]), "parent": int(a[1]), "device": a[2],
                           "root": unescape(a[3]), "target": unescape(a[4]),
                           "vfs_options": a[5].split(","), "fstype": b[0],
                           "source": unescape(b[1]), "fs_options": b[2].split(",")})
        except (ValueError, IndexError) as error:
            raise MountNotReady("Malformed kernel mount metadata") from error
    return mounts


def validate_source(source):
    try:
        host, path = source.split(":", 1)
        ip = ipaddress.IPv4Address(host)
    except (ValueError, AttributeError) as error:
        raise MountNotReady("Expected a literal IPv4 controller and fixed input export") from error
    if path != EXPORT or ip.is_loopback or ip.is_multicast or ip.is_unspecified or ip.is_reserved or ip.is_link_local:
        raise MountNotReady("Unsafe controller input source")
    return str(ip) + ":" + EXPORT


def require_input_mount(source, mountinfo=None):
    source = validate_source(source)
    text = Path("/proc/self/mountinfo").read_text() if mountinfo is None else mountinfo
    mounts = parse_mountinfo(text)
    exact = [m for m in mounts if m["target"] == INPUTS]
    nfs = [m for m in exact if m["fstype"] in ("nfs", "nfs4")]
    if len(nfs) != 1 or any(m["fstype"] not in ("autofs", "nfs", "nfs4") for m in exact) or len(exact) > 2:
        raise MountNotReady("Exact input NFS mount absent or shadowed; an ordinary directory/autofs is not ready")
    mount = nfs[0]
    if mount["source"] != source or mount["root"] != "/":
        raise MountNotReady("Wrong input source or bind-subdirectory mount")
    by_id = {item["id"]: item for item in mounts}
    if len(by_id) != len(mounts):
        raise MountNotReady("Duplicate kernel mount identity")
    ancestors = set()
    current = mount
    while current is not None:
        if current["id"] in ancestors:
            raise MountNotReady("Cyclic kernel mount ancestry")
        ancestors.add(current["id"])
        current = by_id.get(current["parent"])
    for item in mounts:
        target = item["target"]
        if target != INPUTS and (target == "/" or INPUTS.startswith(target.rstrip("/") + "/")) and item["id"] not in ancestors:
            raise MountNotReady("Input mount hidden by an ancestor overmount")
    values = set(mount["vfs_options"]) | set(mount["fs_options"])
    if not REQUIRED <= values or values & FORBIDDEN or "ro" not in mount["vfs_options"]:
        raise MountNotReady("Input mount lacks required read-only/security/protocol options")
    if any(m["target"].startswith(INPUTS + "/") for m in mounts):
        raise MountNotReady("Unexpected nested mount inside input tree")
    return {"ready": True, "mount_id": mount["id"], "source": source, "target": INPUTS,
            "version": "4.1", "scope": "Metadata admission only; not server liveness, authorization or byte verification"}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", required=True)
    args = parser.parse_args(argv)
    try:
        print(json.dumps(require_input_mount(args.source), sort_keys=True))
        return 0
    except (MountNotReady, OSError) as error:
        print(json.dumps({"ready": False, "error": str(error)}, sort_keys=True))
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

backends.py.source:
"""Filesystem adapters for trusted services, without mounting or database side effects.

Keys are authorized, canonical relative file paths, not arbitrary student paths or
an authorization mechanism. The caller must bind them to an owned job/manifest.
All roots and parent directories must be protected from untrusted writers.
"""

from contextlib import contextmanager
import errno
import hashlib
import os
from pathlib import Path, PurePosixPath
import re
import secrets
import stat
from typing import BinaryIO, ContextManager, Iterator, Protocol, runtime_checkable


@runtime_checkable
class StorageBackend(Protocol):
    """Input-file access only; no job states, transport, cache or DB policy.

    Existence/path queries are advisory. Use open_artifact for a no-follow read,
    and verify bytes against the authorized manifest at staging time. I/O errors
    (including NFS outages) propagate; they must not masquerade as cache misses.
    """

    def artifact_exists(self, key: str) -> bool:
        """Return False only for a missing file/parent; reject unsafe file types."""
        ...

    def resolve_path(self, key: str) -> Path:
        """Return the checked existing path for diagnostics, not a safe-open token."""
        ...

    def open_artifact(self, key: str) -> ContextManager[BinaryIO]:
        """Open a regular input file read-only without following any symlink."""
        ...

    def publish_artifact(
        self, key: str, source: BinaryIO, *, expected_sha256: str, expected_size: int
    ) -> Path:
        """Publish a verified new file without replacement, or reject writes.

        Only a trusted controller-side publisher may use this operation. It does
        not commit a manifest/checkpoint or authenticate a caller.
        """
        ...


def _root(path: Path) -> Path:
    result = Path(path)
    if not result.is_absolute() or ".." in result.parts or result == Path("/"):
        raise ValueError("Storage roots must be explicit absolute directories, not /")
    return result


def _parts(key: str) -> tuple[str, ...]:
    if not isinstance(key, str):
        raise ValueError("Artifact key must be a canonical relative POSIX path")
    path = PurePosixPath(key)
    if (
        not key
        or path.is_absolute()
        or not path.parts
        or ".." in path.parts
        or path.as_posix() != key
        or any(char in key for char in ("\\", ":", "\0"))
    ):
        raise ValueError("Artifact key must be a canonical relative POSIX path")
    return path.parts


@contextmanager
def _directory(path: Path) -> Iterator[int]:
    """Anchor every absolute path component with no-follow directory descriptors."""
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW
    fd = os.open(path.anchor, flags)
    try:
        for part in path.parts[1:]:
            child = os.open(part, flags, dir_fd=fd)
            os.close(fd)
            fd = child
        yield fd
    finally:
        os.close(fd)


class _FilesystemReader:
    def __init__(self, root: Path):
        self.root = _root(root)

    @contextmanager
    def _parent(self, key: str) -> Iterator[tuple[int, str]]:
        parts = _parts(key)
        with _directory(self.root.joinpath(*parts[:-1])) as fd:
            yield fd, parts[-1]

    @contextmanager
    def open_artifact(self, key: str) -> Iterator[BinaryIO]:
        with self._parent(key) as (parent, name):
            # NONBLOCK prevents a malicious FIFO from hanging before fstat rejects it.
            fd = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=parent)
        try:
            if not stat.S_ISREG(os.fstat(fd).st_mode):
                raise ValueError("Artifact must be a regular file")
            stream = os.fdopen(fd, "rb")
        except BaseException:
            os.close(fd)
            raise
        with stream:
            yield stream

    def artifact_exists(self, key: str) -> bool:
        try:
            with self.open_artifact(key):
                return True
        except FileNotFoundError:
            return False

    def resolve_path(self, key: str) -> Path:
        with self.open_artifact(key):
            return self.root.joinpath(*_parts(key))


class LegacyStorageBackend(_FilesystemReader):
    """Local view of existing files; does not replace job_storage.stage_job.

    Publication is disabled unless an explicit private staging directory is
    supplied. Provision roots/target parents separately: this adapter never
    creates them. Staging must be outside the input root on the same filesystem.
    """

    def __init__(self, root: Path, *, staging_root: Path | None = None):
        super().__init__(root)
        self.staging_root = _root(staging_root) if staging_root is not None else None
        if self.staging_root is not None and (
            self.root.is_relative_to(self.staging_root)
            or self.staging_root.is_relative_to(self.root)
        ):
            raise ValueError("Publication staging and input roots must not overlap")

    def publish_artifact(
        self, key: str, source: BinaryIO, *, expected_sha256: str, expected_size: int
    ) -> Path:
        if self.staging_root is None:
            raise PermissionError("Controller publication requires a private staging root")
        _parts(key)
        if not isinstance(expected_sha256, str) or not re.fullmatch(r"[0-9a-f]{64}", expected_sha256):
            raise ValueError("Expected SHA-256 must be 64 lowercase hexadecimal characters")
        if type(expected_size) is not int or expected_size < 0:
            raise ValueError("Expected size must be a nonnegative integer")
        with self._parent(key) as (parent, name), _directory(self.staging_root) as staging:
            staging_info = os.fstat(staging)
            if staging_info.st_uid != os.geteuid() or staging_info.st_mode & 0o077:
                raise PermissionError("Publication staging must be owner-only (0700)")
            if staging_info.st_dev != os.fstat(parent).st_dev:
                raise OSError(errno.EXDEV, "Publication staging must be on the input filesystem")
            temporary = ".artifact-" + secrets.token_hex(16)
            fd = os.open(
                temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                0o600, dir_fd=staging,
            )
            try:
                with os.fdopen(fd, "wb") as outgoing:
                    actual_hash = hashlib.sha256()
                    size = 0
                    while True:
                        chunk = source.read(min(1024 * 1024, expected_size - size + 1))
                        if not chunk:
                            break
                        size += len(chunk)
                        if size > expected_size:
                            raise ValueError("Artifact exceeds expected size")
                        actual_hash.update(chunk)
                        outgoing.write(chunk)
                    if size != expected_size or actual_hash.hexdigest() != expected_sha256:
                        raise ValueError("Artifact size or SHA-256 does not match")
                    outgoing.flush()
                    os.fchmod(outgoing.fileno(), 0o444)
                    os.fsync(outgoing.fileno())
                # A same-filesystem link atomically creates the final name without
                # replacing an existing file (unlike rename/replace). The temporary
                # inode is our private copy, never a mutable student/cache file.
                os.link(temporary, name, src_dir_fd=staging, dst_dir_fd=parent, follow_symlinks=False)
                os.fsync(parent)
            finally:
                os.unlink(temporary, dir_fd=staging)
            # A directory-fsync error after link can leave a complete file visible;
            # callers must reconcile before retry, never overwrite it.
        return self.root.joinpath(*_parts(key))


class NFSStorageBackend(_FilesystemReader):
    """Read-only view of a pre-mounted input export; no mount or network setup.

    The controller publishes through a separate LegacyStorageBackend on its local
    export directory. The worker adapter never writes, even if a mount is RW.
    It does not attest mount flags, host isolation, authentication or NFS health.
    """

    def publish_artifact(
        self, key: str, source: BinaryIO, *, expected_sha256: str, expected_size: int
    ) -> Path:
        raise PermissionError(errno.EROFS, "NFS input access is read-only; use the trusted controller publisher")

nfs_server.py.source:
"""Plan and stage one narrowly scoped NFS server configuration; never activate it.

The CLI defaults to a read-only plan. Future --apply stages directories/config
only, requires root and the current reviewed plan digest, and makes a backup
first. Package installation, exportfs and systemd activation are separate actions.
"""

import argparse
from datetime import datetime, timezone
import hashlib
import fcntl
import ipaddress
import json
import os
from pathlib import Path
import pwd
import grp
import re
import stat
import subprocess
import tempfile
import uuid

SHARED = "/srv/ml-shared"
OBJECTS = SHARED + "/objects"
STAGING = SHARED + "/.publish"
MARKER = SHARED + "/.nfs-setup.json"
EXPORTS = "/etc/exports.d/distributed-ml.exports"
BACKUPS = "/var/backups/distributed-ml-nfs"
HEADER = "# Managed by distributed-dl-system nfs-server v1\n"
CONFIG_FILE = Path(__file__).resolve().parents[1] / "config/nfs-server.json"
MAX_BYTES = 256 * 1024
LOCAL_FILESYSTEMS = {"ext4", "ext3", "ext2", "xfs", "btrfs", "f2fs", "overlay", "tmpfs"}


class SetupError(ValueError):
    """A proposed setup cannot be safely interpreted or applied."""


def encoded(value):
    return (json.dumps(value, sort_keys=True, separators=(",", ":")) + "\n").encode()


def digest(value):
    return hashlib.sha256(encoded(value)).hexdigest()


def _unique(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise SetupError("Duplicate configuration field: " + key)
        result[key] = value
    return result


def address(value):
    if type(value) is not str:
        raise SetupError("Clients/server must be literal IPv4 host addresses")
    try:
        ip = ipaddress.IPv4Address(value)
    except ipaddress.AddressValueError as error:
        raise SetupError("Clients/server must be literal IPv4 host addresses") from error
    if ip.is_loopback or ip.is_multicast or ip.is_unspecified or ip.is_link_local or ip.is_reserved or int(ip) == 0xffffffff:
        raise SetupError("Use a routable, explicitly reviewed IPv4 host address")
    return str(ip)


def selected_nodes(config):
    """Default to all three; a smaller deployment requires an explicit selection."""
    nodes = config.get("deployment_nodes", ["pi01", "pi02", "pi03"])
    if not isinstance(nodes, list) or not nodes or any(type(node) is not str or node not in {"pi01", "pi02", "pi03"} for node in nodes) or len(nodes) != len(set(nodes)):
        raise SetupError("deployment_nodes must be a nonempty unique list of known Pi IDs")
    return sorted(nodes)


def validate_config(value):
    fields = {"schema_version", "server_address", "clients", "publisher_uid", "publisher_gid", "layout"}
    if not isinstance(value, dict) or set(value) not in (fields, fields | {"deployment_nodes"}) or type(value["schema_version"]) is not int or value["schema_version"] != 1:
        raise SetupError("Expected exactly the version-one NFS server configuration fields")
    selected_nodes(value)
    address(value["server_address"])
    clients = value["clients"]
    if not isinstance(clients, dict) or set(clients) != {"pi01", "pi02", "pi03"}:
        raise SetupError("Explicitly list pi01, pi02 and pi03; unknown addresses must be null")
    known = [address(ip) for ip in clients.values() if ip is not None]
    if len(set(known)) != len(known) or value["server_address"] in known:
        raise SetupError("Client addresses must be distinct and different from the server")
    for field in ("publisher_uid", "publisher_gid"):
        number = value[field]
        if number is not None and (type(number) is not int or not 1 <= number < 2**31):
            raise SetupError(field + " must be an existing dedicated non-root identity, or null")
    if value["layout"] not in ("subdirectory", "dedicated-filesystem"):
        raise SetupError("layout must be subdirectory or dedicated-filesystem")
    return value


def load_config(path):
    with Path(path).open("rb") as stream:
        raw = stream.read(MAX_BYTES + 1)
    if len(raw) > MAX_BYTES:
        raise SetupError("NFS server configuration is too large")
    return validate_config(json.loads(raw.decode("utf-8"), object_pairs_hook=_unique))


def options(layout):
    if layout == "dedicated-filesystem":
        return "ro,sync,root_squash,no_subtree_check,mountpoint,secure,sec=sys"
    return "ro,sync,root_squash,subtree_check,secure,sec=sys"


def render_exports(config):
    entries = [ip + "(" + options(config["layout"]) + ")"
               for node, ip in sorted(config["clients"].items()) if node in selected_nodes(config) and ip is not None]
    return HEADER + (OBJECTS + " " + " ".join(entries) + "\n" if entries else "")


def check_exports(text, *, managed=False):
    """Conservative syntax/policy checker, not the complete nfs-utils grammar.

    Unmanaged tables may contain comments only: refuse, never reinterpret or
    activate existing unrelated exports. Managed rows allow only this exact root,
    literal hosts and fixed safe options. Unknown syntax is a review blocker.
    """
    if managed and not text.startswith(HEADER):
        raise SetupError("Existing managed filename lacks our ownership marker")
    rows = [line.strip() for line in text.splitlines() if line.strip() and not line.lstrip().startswith("#")]
    if not managed:
        if rows:
            raise SetupError("Unmanaged noncomment exports require separate syntax/policy review")
        return []
    if len(rows) > 1:
        raise SetupError("Managed export must contain exactly one input-only export row")
    clients = []
    for line in rows:
        parts = line.split()
        if not parts or parts[0] != OBJECTS or len(parts) < 2:
            raise SetupError("Only the dedicated immutable objects path may be exported")
        for part in parts[1:]:
            match = re.fullmatch(r"([0-9.]+)\(([^()]*)\)", part)
            if not match or match[2] not in (options("subdirectory"), options("dedicated-filesystem")):
                raise SetupError("Malformed or unsafe export client/options")
            clients.append(address(match[1]))
    if len(set(clients)) != len(clients):
        raise SetupError("Duplicate export client")
    return clients


def check_active_table(text, config):
    """Accept only this export's reviewed literal clients and safe known defaults."""
    allowed = set(options(config["layout"]).split(",")) | {
        "wdelay", "hide", "nocrossmnt", "no_all_squash", "secure_locks", "acl",
        "no_pnfs", "anonuid=65534", "anongid=65534",
    }
    expected_clients = {config["clients"][node] for node in selected_nodes(config) if config["clients"][node] is not None}
    for line in text.splitlines():
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        parts = line.split()
        if len(parts) < 2 or parts[0] != OBJECTS:
            raise SetupError("Unexpected existing active export path")
        for client in parts[1:]:
            match = re.fullmatch(r"([0-9.]+)\(([^()]*)\)", client)
            if not match or address(match[1]) not in expected_clients:
                raise SetupError("Unexpected active export client")
            values = set(match[2].split(","))
            if not set(options(config["layout"]).split(",")) <= values or not values <= allowed:
                raise SetupError("Active export options require separate review")


class Host:
    """All paths are fixed logical host paths; tests use an isolated fake root."""

    def __init__(self, root=Path("/"), admin_uid=0):
        self.root = Path(root)
        self.admin_uid = admin_uid

    def path(self, logical):
        return self.root / logical.lstrip("/")

    def facts(self):
        def run(args):
            result = subprocess.run(args, capture_output=True, text=True, timeout=5)
            if result.returncode:
                raise SetupError("Read-only prerequisite query failed: " + " ".join(args))
            return result.stdout
        packages = {}
        for name in ("nfs-kernel-server", "nfs-common"):
            result = subprocess.run(["dpkg-query", "-W", "-f=${Status}", name], capture_output=True, text=True, timeout=5)
            packages[name] = result.returncode == 0 and result.stdout == "install ok installed"
        interfaces = json.loads(run(["ip", "-j", "address", "show"]))
        addresses = sorted(a["local"] for i in interfaces for a in i.get("addr_info", []) if a.get("family") == "inet")
        mounts = []
        for line in Path("/proc/self/mountinfo").read_text().splitlines():
            left, right = line.split(" - ", 1)
            a, b = left.split(), right.split()
            target = re.sub(r"\\([0-7]{3})", lambda m: chr(int(m[1], 8)), a[4])
            mounts.append({"target": target, "root": a[3], "device": a[2], "fstype": b[0]})
        return {"packages": packages, "addresses": addresses, "mounts": mounts}

    def metadata(self, logical, mounts):
        path = self.path(logical)
        for parent in [*reversed(path.relative_to(self.root).parents), path.relative_to(self.root)]:
            logical_parent = "/" if parent == Path(".") else "/" + parent.as_posix()
            matches = [m for m in mounts if logical_parent == m["target"] or logical_parent.startswith(m["target"].rstrip("/") + "/")]
            if matches and max(matches, key=lambda m: len(m["target"]))["fstype"] not in LOCAL_FILESYSTEMS:
                raise SetupError("Refusing remote/automount/unknown filesystem traversal: " + logical)
            actual = self.root / parent
            try:
                info = actual.lstat()
            except FileNotFoundError:
                return None
            if stat.S_ISLNK(info.st_mode):
                raise SetupError("Symlink in host setup path: " + str(actual))
            if actual != path and (not stat.S_ISDIR(info.st_mode) or info.st_uid != self.admin_uid or info.st_mode & 0o022):
                raise SetupError("Host setup ancestor is not a protected admin directory: " + str(actual))
        return {"uid": info.st_uid, "gid": info.st_gid, "mode": stat.S_IMODE(info.st_mode),
                "directory": stat.S_ISDIR(info.st_mode), "regular": stat.S_ISREG(info.st_mode)}

    def read(self, logical, mounts):
        info = self.metadata(logical, mounts)
        if info is None:
            return None
        if not info["regular"]:
            raise SetupError("Expected a regular administrative file: " + logical)
        with self.path(logical).open("rb") as stream:
            raw = stream.read(MAX_BYTES + 1)
        if len(raw) > MAX_BYTES:
            raise SetupError("Administrative file exceeds inspection bound: " + logical)
        return {"text": raw.decode("utf-8"), **info, "sha256": hashlib.sha256(raw).hexdigest()}


def build_plan(config, host=None):
    config = validate_config(config)
    host = host or Host()
    facts = host.facts()
    blockers = []
    admin_directories = {}
    for name in ("/srv", "/etc", "/var/backups", BACKUPS):
        info = host.metadata(name, facts["mounts"])
        admin_directories[name] = info
        if info and (not info["directory"] or info["uid"] != host.admin_uid or info["mode"] & 0o022):
            raise SetupError("Unprotected administrative directory: " + name)
        if info is None and name != BACKUPS:
            blockers.append("Required administrative parent directory missing: " + name)
    for node, ip in config["clients"].items():
        if node in selected_nodes(config) and ip is None:
            blockers.append(node + ": verified client address missing; never broaden the allowlist to compensate")
    if config["server_address"] not in facts["addresses"]:
        blockers.append("Proposed server address is not currently assigned to this controller")
    for name, installed in facts["packages"].items():
        if not installed:
            blockers.append(name + " missing: package provisioning needs separate approval; script never installs it")
    for name in ("publisher_uid", "publisher_gid"):
        if config[name] is None:
            blockers.append(name + " missing: review/preprovision the dedicated trusted publisher identity")
    if host.root == Path("/") and config["publisher_uid"] is not None and config["publisher_gid"] is not None:
        try:
            pwd.getpwuid(config["publisher_uid"])
            grp.getgrgid(config["publisher_gid"])
        except KeyError:
            blockers.append("Publisher UID/GID must already exist; no account creation is performed")
    files = {}
    names = ["/etc/exports", EXPORTS]
    directory = host.metadata("/etc/exports.d", facts["mounts"])
    if directory:
        if not directory["directory"] or directory["uid"] != host.admin_uid or directory["mode"] & 0o022:
            raise SetupError("exports.d must be a protected admin directory")
        candidates = sorted(p.name for p in host.path("/etc/exports.d").iterdir() if p.name.endswith(".exports") and not p.name.startswith("."))
        if len(candidates) > 32:
            raise SetupError("Too many export tables for this bounded preparer")
        names += ["/etc/exports.d/" + name for name in candidates]
    for name in sorted(set(names)):
        record = host.read(name, facts["mounts"])
        files[name] = record
        if record:
            if record["uid"] != host.admin_uid or record["mode"] & 0o022:
                raise SetupError("Export configuration must be admin-owned and not group/world writable")
            check_exports(record["text"], managed=name == EXPORTS)
    # Read the managed export table directly; do not invoke exportfs for inspection.
    etab = host.read("/var/lib/nfs/etab", facts["mounts"])
    if etab:
        if etab["uid"] != host.admin_uid or etab["mode"] & 0o022:
            raise SetupError("Active export table must be protected admin-owned metadata")
        check_active_table(etab["text"], config)
    dirs = {name: host.metadata(name, facts["mounts"]) for name in (SHARED, OBJECTS, STAGING)}
    marker = host.read(MARKER, facts["mounts"])
    expected_marker = {"version": 1, "objects": OBJECTS, "publisher_uid": config["publisher_uid"], "publisher_gid": config["publisher_gid"]}
    if marker:
        if marker["uid"] != host.admin_uid or marker["mode"] != 0o600 or json.loads(marker["text"]) != expected_marker:
            raise SetupError("Existing setup marker differs; never change publisher ownership automatically")
    elif dirs[SHARED] and any(host.path(SHARED).iterdir()):
        raise SetupError("Refusing to adopt nonempty unmarked /srv/ml-shared")
    expected = {SHARED: (host.admin_uid, None, 0o755), OBJECTS: (config["publisher_uid"], config["publisher_gid"], 0o755), STAGING: (config["publisher_uid"], config["publisher_gid"], 0o700)}
    for name, current in dirs.items():
        uid, gid, mode = expected[name]
        if current and (not current["directory"] or current["mode"] != mode or (uid is not None and current["uid"] != uid) or (gid is not None and current["gid"] != gid)):
            raise SetupError("Existing directory attributes differ; no chown/chmod of existing data: " + name)
    mount = next((m for m in facts["mounts"] if m["target"] == OBJECTS), None)
    parent_mounts = [m for m in facts["mounts"] if SHARED == m["target"] or SHARED.startswith(m["target"].rstrip("/") + "/")]
    parent_mount = max(parent_mounts, key=lambda m: len(m["target"])) if parent_mounts else None
    if config["layout"] == "dedicated-filesystem" and not (mount and mount["root"] == "/" and parent_mount and mount["device"] != parent_mount["device"]):
        blockers.append("no_subtree_check requires a mounted whole dedicated filesystem, not a bind/empty directory")
    desired = render_exports(config)
    check_exports(desired, managed=True)
    observed = {"facts": facts, "config_files": files, "active_table": etab, "directories": dirs,
                "marker": marker, "exports_directory": directory, "admin_directories": admin_directories}
    plan = {"version": 1, "config": config, "desired_exports": desired, "observed": observed,
            "blockers": blockers, "apply_ready": not blockers, "mode": "dry-run",
            "scope": "Stage configuration only; never install packages, activate exports or change services",
            "proposed_directories": [
                {"path": SHARED, "uid": host.admin_uid, "gid": "admin primary group", "mode": "0755"},
                {"path": OBJECTS, "uid": config["publisher_uid"], "gid": config["publisher_gid"], "mode": "0755"},
                {"path": STAGING, "uid": config["publisher_uid"], "gid": config["publisher_gid"], "mode": "0700"}],
            "config_file_to_stage": EXPORTS, "existing_data_policy": "Verify existing attributes; never recurse, delete or change them",
            "package_command_for_separate_review_only": ["apt-get", "--no-download", "install", "nfs-kernel-server", "nfs-common"],
            "activation_after_separate_approval": ["systemctl start nfs-server.service", "exportfs -ra"],
            "backup_before_changes": BACKUPS, "syntax_check": "Conservative managed grammar; unmanaged files must be comments/empty. Native exportfs not invoked."}
    plan["plan_sha256"] = digest(plan)
    return plan


def _write_new(path, raw, mode, uid, gid):
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, mode)
    with os.fdopen(fd, "wb") as stream:
        stream.write(raw)
        stream.flush()
        os.fchmod(stream.fileno(), mode)
        os.fchown(stream.fileno(), uid, gid)
        os.fsync(stream.fileno())


def _sync(path):
    fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def stage_configuration(config, reviewed_sha256, host=None):
    """Future root-only configuration staging. Never call without user approval.

    A matching digest binds review to current facts; it is not itself permission.
    Failures leave backups and any new directories intact, without activating NFS.
    """
    host = host or Host()
    if os.geteuid() != host.admin_uid:
        raise SetupError("Configuration staging requires the host administrator")
    plan = build_plan(config, host)
    if reviewed_sha256 != plan["plan_sha256"]:
        raise SetupError("Current plan differs from reviewed digest; review a fresh dry-run")
    if plan["blockers"]:
        raise SetupError("Cannot stage configuration: " + "; ".join(plan["blockers"]))
    current = plan["observed"]["config_files"][EXPORTS]
    if current and current["text"] == plan["desired_exports"] and plan["observed"]["marker"] and all(plan["observed"]["directories"].values()):
        return {"status": "no_changes", "activated": False}
    # Only future explicitly approved staging creates this private lock. Dry-runs
    # do not create it. Protected /etc and no-follow prevent untrusted lock paths.
    lock = host.path("/etc/.distributed-ml-nfs.lock")
    fd = os.open(lock, os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
    try:
        info = os.fstat(fd)
        if not stat.S_ISREG(info.st_mode) or info.st_uid != host.admin_uid or stat.S_IMODE(info.st_mode) != 0o600 or info.st_nlink != 1:
            raise SetupError("Unprotected NFS setup lock")
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        fresh = build_plan(config, host)
        if fresh["plan_sha256"] != reviewed_sha256 or fresh["blockers"]:
            raise SetupError("Controller changed while obtaining setup lock; review again")
        return _stage_reviewed(fresh, host)
    finally:
        os.close(fd)


def _stage_reviewed(plan, host):
    config = plan["config"]
    state = plan["observed"]
    mounts = state["facts"]["mounts"]
    # Check all administrative ancestors before any creation. No recursive fixups.
    for name in ("/srv", "/etc", "/var/backups", BACKUPS):
        info = host.metadata(name, mounts)
        if info and (not info["directory"] or info["uid"] != host.admin_uid or info["mode"] & 0o022):
            raise SetupError("Unprotected administrative directory: " + name)
    backup_root = host.path(BACKUPS)
    backup_root.mkdir(mode=0o700, exist_ok=True)
    _sync(backup_root.parent)
    backup = backup_root / (datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ") + "-" + uuid.uuid4().hex)
    backup.mkdir(mode=0o700)
    record = {"reviewed_plan_sha256": plan["plan_sha256"], "files": state["config_files"],
              "installed_exports_sha256": hashlib.sha256(plan["desired_exports"].encode()).hexdigest(),
              "restore_scope": "Restore only the managed drop-in after hash/ownership checks; other exports were never modified. Preserve all input/staging directories."}
    _write_new(backup / "before.json", encoded(record), 0o600, host.admin_uid, os.getegid())
    _sync(backup)
    _sync(backup_root)
    def create_directory(name, uid, gid, mode):
        if not host.path(name).exists():
            host.path(name).mkdir(mode=mode)
            os.chown(host.path(name), uid, gid)
            os.chmod(host.path(name), mode)
            _sync(host.path(name).parent)
    create_directory(SHARED, host.admin_uid, os.getegid(), 0o755)
    if state["marker"] is None:
        marker = {"version": 1, "objects": OBJECTS, "publisher_uid": config["publisher_uid"], "publisher_gid": config["publisher_gid"]}
        _write_new(host.path(MARKER), encoded(marker), 0o600, host.admin_uid, os.getegid())
        _sync(host.path(SHARED))
    # The marker precedes child directories, so interrupted setup can be safely
    # resumed without adopting an unmarked nonempty directory.
    create_directory(OBJECTS, config["publisher_uid"], config["publisher_gid"], 0o755)
    create_directory(STAGING, config["publisher_uid"], config["publisher_gid"], 0o700)
    host.path("/etc/exports.d").mkdir(mode=0o755, exist_ok=True)
    _sync(host.path("/etc"))
    fd, temporary = tempfile.mkstemp(prefix=".distributed-ml-", dir=host.path("/etc/exports.d"))
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(plan["desired_exports"].encode())
            stream.flush()
            os.fchmod(stream.fileno(), 0o644)
            os.fchown(stream.fileno(), host.admin_uid, os.getegid())
            os.fsync(stream.fileno())
        if host.read(EXPORTS, mounts) != state["config_files"][EXPORTS]:
            raise SetupError("Managed config changed before publication; preserving it")
        if state["config_files"][EXPORTS] is None:
            os.link(temporary, host.path(EXPORTS), follow_symlinks=False)
        else:
            os.replace(temporary, host.path(EXPORTS))
        _sync(host.path("/etc/exports.d"))
    finally:
        Path(temporary).unlink(missing_ok=True)
    return {"status": "configuration_staged_not_activated", "backup": str(backup), "activated": False}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", type=Path, default=CONFIG_FILE)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--dry-run", action="store_true", help="Read-only plan (also the default)")
    mode.add_argument("--apply", action="store_true", help="Future approved root-only config staging; never activates NFS")
    parser.add_argument("--reviewed-plan-sha256", help="Required with --apply, after explicit approval")
    args = parser.parse_args(argv)
    try:
        config = load_config(args.config)
        if args.apply:
            if not args.reviewed_plan_sha256:
                raise SetupError("--apply requires a current --reviewed-plan-sha256 and prior user approval")
            result = stage_configuration(config, args.reviewed_plan_sha256)
        else:
            if args.reviewed_plan_sha256:
                raise SetupError("Review digest is only used with --apply")
            result = build_plan(config)
        print(json.dumps(result, indent=2, sort_keys=True))
        return 2 if result.get("blockers") else 0
    except (SetupError, OSError, ValueError, subprocess.SubprocessError) as error:
        parser.exit(2, "NFS server setup refused: " + str(error) + "\n")


if __name__ == "__main__":
    raise SystemExit(main())

nfs_client.py.source:
"""Prepare boot-independent NFS client units; default is an offline selected-Pi plan.

--inspect-local requires an explicit node and only reads local state. Future
approved administrator actions provision a missing package or stage config;
neither enables units, activates mounts, edits fstab or alters the legacy agent.
"""

import argparse
from datetime import datetime, timezone
import fcntl
import hashlib
import json
import os
from pathlib import Path
import shutil
import stat
import subprocess
import uuid

from .nfs_mount import INPUTS, EXPORT, parse_mountinfo, unescape
from .nfs_server import Host, SetupError, MAX_BYTES, address, digest, encoded, selected_nodes, _unique, _write_new, _sync

CONFIG_FILE = Path(__file__).resolve().parents[1] / "config/nfs-clients.json"
ROOT = "/srv/mlnfs"
MARKER = ROOT + "/.nfs-client-setup.json"
LIBEXEC = "/usr/local/libexec/distributed-ml"
GUARD = LIBEXEC + "/nfs_mount.py"
MOUNT = "srv-mlnfs-inputs.mount"
AUTOMOUNT = "srv-mlnfs-inputs.automount"
READY = "ml-nfs-ready.service"
UNITS = "/etc/systemd/system"
BACKUPS = "/var/backups/distributed-ml-nfs-client"
LOCK = "/etc/.distributed-ml-nfs-client.lock"
HEADER = "# Managed by distributed-dl-system nfs-client v1\n"
MOUNT_OPTIONS = "ro,nosuid,nodev,noexec,hard,vers=4.1,proto=tcp,sec=sys,resvport,timeo=50,retrans=2,retry=0,nofail"
PACKAGE_COMMAND = ["/usr/bin/apt-get", "--no-download", "--no-remove", "--assume-yes", "install", "nfs-common"]
QUERY_ENV = {"PATH": "/usr/sbin:/usr/bin:/sbin:/bin", "LC_ALL": "C"}


def validate_config(config):
    fields = {"schema_version", "server_address", "clients"}
    if not isinstance(config, dict) or set(config) not in (fields, fields | {"deployment_nodes"}) or type(config["schema_version"]) is not int or config["schema_version"] != 1:
        raise SetupError("Expected exactly version-one NFS client fields")
    selected_nodes(config)
    address(config["server_address"])
    clients = config["clients"]
    if not isinstance(clients, dict) or set(clients) != {"pi01", "pi02", "pi03"}:
        raise SetupError("List all three Pis, with null for unknown LAN addresses")
    known = [address(value) for value in clients.values() if value is not None]
    if len(known) != len(set(known)) or config["server_address"] in known:
        raise SetupError("Clients must be distinct and different from the controller")
    return config


def load_config(path):
    with Path(path).open("rb") as stream:
        raw = stream.read(MAX_BYTES + 1)
    if len(raw) > MAX_BYTES:
        raise SetupError("Client proposal is too large")
    return validate_config(json.loads(raw.decode(), object_pairs_hook=_unique))


def source(config):
    return config["server_address"] + ":" + EXPORT


def render_files(config, node):
    validate_config(config)
    if node not in selected_nodes(config):
        raise SetupError("Selected Pi is excluded from this deployment")
    mount = HEADER + "\n".join([
        "[Unit]", "Description=Distributed ML trusted input mount (" + node + ")",
        "[Mount]", "What=" + source(config), "Where=" + INPUTS, "Type=nfs",
        "Options=" + MOUNT_OPTIONS, "TimeoutSec=15s", "DirectoryMode=0700", ""])
    automount = HEADER + "\n".join([
        "[Unit]", "Description=Distributed ML on-demand input automount (" + node + ")",
        "[Automount]", "Where=" + INPUTS, "DirectoryMode=0700", "TimeoutIdleSec=0",
        "[Install]", "WantedBy=multi-user.target", ""])
    ready = HEADER + "\n".join([
        "[Unit]", "Description=Distributed ML input mount admission (" + node + ")",
        "Requires=" + MOUNT, "After=" + MOUNT,
        "[Service]", "Type=oneshot", "User=root", "Group=root", "UMask=0077",
        "ExecStart=/usr/bin/python3 -I " + GUARD + " --source " + source(config),
        "NoNewPrivileges=yes", "ProtectSystem=strict", "ProtectHome=yes", "PrivateTmp=yes",
        "TimeoutStartSec=5s", ""])
    guard = HEADER + Path(__file__).with_name("nfs_mount.py").read_text()
    return {UNITS + "/" + MOUNT: mount, UNITS + "/" + AUTOMOUNT: automount,
            UNITS + "/" + READY: ready, GUARD: guard}


def plan_all(config):
    validate_config(config)
    nodes = selected_nodes(config)
    blockers = [node + ": verified LAN address missing; deployment remains deferred"
                for node in nodes if config["clients"][node] is None]
    return {"version": 1, "mode": "offline-three-client-preview" if len(nodes) == 3 else "offline-selected-client-preview", "config": config,
            "apply_ready": False, "blockers": blockers + ["Fresh local inspection on each Pi and explicit 2.4 approval required"],
            "clients": {node: {"address": config["clients"][node], "files": render_files(config, node)} for node in nodes},
            "package_if_missing_after_approval": PACKAGE_COMMAND,
            "activation_after_separate_approval": ["systemctl daemon-reload", "systemctl enable --now " + AUTOMOUNT],
            "fstab_policy": "Never written; existing mount and agent units unchanged",
            "runtime_enablement": "Blocked until authorization, job isolation and supervised staging are implemented"}


class ClientHost(Host):
    def facts(self):
        result = subprocess.run(["dpkg-query", "-W", "-f=${Status}", "nfs-common"], capture_output=True, text=True, timeout=5, env=QUERY_ENV)
        installed = result.returncode == 0 and result.stdout == "install ok installed"
        result = subprocess.run(["ip", "-j", "address", "show"], capture_output=True, text=True, timeout=5, env=QUERY_ENV)
        if result.returncode:
            raise SetupError("Local read-only interface query failed")
        interfaces = json.loads(result.stdout)
        mounts = parse_mountinfo(Path("/proc/self/mountinfo").read_text())
        return {"nfs_common_installed": installed, "mount_helper_available": shutil.which("mount.nfs", path=QUERY_ENV["PATH"]) is not None,
                "addresses": sorted(a["local"] for interface in interfaces for a in interface.get("addr_info", []) if a.get("family") == "inet"),
                "mounts": mounts}


def inspect_local(config, node, host=None):
    validate_config(config)
    if node not in selected_nodes(config):
        raise SetupError("Selected Pi is excluded from this deployment")
    host = host or ClientHost()
    facts = host.facts()
    mounts = facts["mounts"]
    blockers = [name + ": verified LAN address missing" for name in selected_nodes(config) if config["clients"][name] is None]
    if config["clients"][node] not in facts["addresses"]:
        blockers.append("Selected Pi LAN address is not assigned to this host; never apply on the controller")
    if not facts["nfs_common_installed"]:
        blockers.append("nfs-common missing; separate approved offline package provisioning required")
    elif not facts["mount_helper_available"]:
        blockers.append("mount.nfs missing despite installed nfs-common; repair requires review")
    files = render_files(config, node)
    observed = {"facts": facts, "files": {}, "directories": {}}
    for name in ("/srv", "/etc", UNITS, "/var/backups", "/usr/local", "/usr/local/libexec", LIBEXEC, BACKUPS):
        current = host.metadata(name, mounts)
        observed["directories"][name] = current
        if current and (not current["directory"] or current["uid"] != host.admin_uid or current["mode"] & 0o022):
            raise SetupError("Unprotected administrative directory: " + name)
        if current is None and name in ("/srv", "/etc", UNITS, "/var/backups", "/usr/local"):
            blockers.append("Required administrative parent missing: " + name)
    fstab = host.read("/etc/fstab", mounts)
    observed["fstab"] = fstab
    if fstab:
        if fstab["uid"] != host.admin_uid or fstab["mode"] & 0o022:
            raise SetupError("Unprotected fstab; never overwrite it")
        for line in fstab["text"].splitlines():
            if not line.strip() or line.lstrip().startswith("#"):
                continue
            fields = line.split()
            if len(fields) < 4:
                raise SetupError("Malformed existing fstab requires manual review")
            target = unescape(fields[1])
            if target == ROOT or target.startswith(ROOT + "/"):
                raise SetupError("Conflicting fstab input path; preserve it for manual review")
    # Never stat/traverse mounted input paths, including an autofs trigger.
    occupied = any(m["target"] == ROOT or m["target"].startswith(ROOT + "/") for m in mounts)
    if occupied:
        raise SetupError("Managed input path is already mounted; drain and review before configuration staging")
    for name, mode in ((ROOT, 0o700), (INPUTS, 0o700)):
        current = host.metadata(name, mounts)
        observed["directories"][name] = current
        if current and (not current["directory"] or current["uid"] != host.admin_uid or current["mode"] != mode):
            raise SetupError("Input path must be a protected admin-owned 0700 directory")
    marker = host.read(MARKER, mounts)
    expected_marker = {"version": 1, "node": node, "source": source(config)}
    observed["marker"] = marker
    if marker:
        if marker["uid"] != host.admin_uid or marker["mode"] != 0o600 or json.loads(marker["text"]) != expected_marker:
            raise SetupError("Client setup marker differs; never silently repurpose a mount root")
    elif observed["directories"][ROOT] and any(host.path(ROOT).iterdir()):
        raise SetupError("Refusing nonempty unmarked input root")
    if observed["directories"][INPUTS] and any(host.path(INPUTS).iterdir()):
        raise SetupError("Underlying input mountpoint must be empty; preserve its data")
    for unit in (MOUNT, AUTOMOUNT, READY):
        for base in (UNITS, "/run/systemd/system", "/usr/lib/systemd/system"):
            if host.metadata(base + "/" + unit + ".d", mounts) is not None:
                raise SetupError("Existing unit override requires manual review: " + unit)
            if base != UNITS and host.metadata(base + "/" + unit, mounts) is not None:
                raise SetupError("Existing runtime/vendor unit requires manual review: " + unit)
    for target in ("multi-user.target.wants", "remote-fs.target.wants", "local-fs.target.wants"):
        if host.metadata(UNITS + "/" + target + "/" + MOUNT, mounts) is not None:
            raise SetupError("Direct boot dependency on input mount requires manual review")
    for name in files:
        record = host.read(name, mounts)
        observed["files"][name] = record
        if record and (record["uid"] != host.admin_uid or record["mode"] != 0o644 or not record["text"].startswith(HEADER)):
            raise SetupError("Unowned/unsafe client configuration target: " + name)
    plan = {"version": 1, "mode": "local-read-only-plan", "node": node, "config": config,
            "files": files, "observed": observed, "blockers": blockers, "apply_ready": not blockers,
            "package_if_missing_after_approval": PACKAGE_COMMAND, "backup_before_changes": BACKUPS,
            "scope": "Stage only; never edit fstab, mount, enable/reload units or restart the legacy agent"}
    plan["plan_sha256"] = digest(plan)
    return plan


def _review(config, node, sha, host):
    if os.geteuid() != host.admin_uid:
        raise SetupError("Live client action requires the host administrator and separate approval")
    plan = inspect_local(config, node, host)
    if plan["plan_sha256"] != sha:
        raise SetupError("Local plan changed; review a fresh digest")
    return plan


def provision_package(config, node, sha, host=None):
    """Future explicitly approved offline provisioning; package scripts may affect services."""
    host = host or ClientHost()
    plan = _review(config, node, sha, host)
    if plan["observed"]["facts"]["nfs_common_installed"]:
        return {"status": "package_already_installed", "command_executed": False}
    if any(not blocker.startswith("nfs-common missing;") for blocker in plan["blockers"]):
        raise SetupError("Resolve non-package blockers before offline provisioning")
    result = subprocess.run(PACKAGE_COMMAND, check=True, env={"PATH": "/usr/sbin:/usr/bin:/sbin:/bin", "DEBIAN_FRONTEND": "noninteractive"})
    return {"status": "package_command_completed_review_new_plan", "returncode": result.returncode,
            "command_executed": True, "warning": "Package maintainer scripts may change services; unit staging/activation not performed"}


def stage_configuration(config, node, sha, host=None):
    host = host or ClientHost()
    plan = _review(config, node, sha, host)
    if plan["blockers"]:
        raise SetupError("Client configuration blocked: " + "; ".join(plan["blockers"]))
    state = plan["observed"]
    if state["marker"] and all(state["directories"].get(name) for name in (ROOT, INPUTS, LIBEXEC)) and all(state["files"][name] and state["files"][name]["text"] == text for name, text in plan["files"].items()):
        return {"status": "no_changes", "activated": False}
    fd = os.open(host.path(LOCK), os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
    try:
        info = os.fstat(fd)
        if not stat.S_ISREG(info.st_mode) or info.st_uid != host.admin_uid or stat.S_IMODE(info.st_mode) != 0o600 or info.st_nlink != 1:
            raise SetupError("Unprotected client setup lock")
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        fresh = _review(config, node, sha, host)
        return _stage(fresh, host)
    finally:
        os.close(fd)


def _stage(plan, host):
    state = plan["observed"]
    mounts = state["facts"]["mounts"]
    backup_root = host.path(BACKUPS)
    backup_root.mkdir(mode=0o700, exist_ok=True)
    _sync(backup_root.parent)
    backup = backup_root / (datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ") + "-" + uuid.uuid4().hex)
    backup.mkdir(mode=0o700)
    journal = {"plan_sha256": plan["plan_sha256"], "node": plan["node"], "files": state["files"],
               "fstab_unchanged": state["fstab"],
               "installed_sha256": {name: hashlib.sha256(text.encode()).hexdigest() for name, text in plan["files"].items()},
               "restore_scope": "Only listed managed files after current hash checks; preserve data, fstab, unrelated units and backups"}
    _write_new(backup / "before.json", encoded(journal), 0o600, host.admin_uid, os.getegid())
    _sync(backup)
    _sync(backup_root)
    def directory(name, mode):
        if not host.path(name).exists():
            host.path(name).mkdir(mode=mode)
            os.chmod(host.path(name), mode)
            _sync(host.path(name).parent)
    directory(ROOT, 0o700)
    if state["marker"] is None:
        _write_new(host.path(MARKER), encoded({"version": 1, "node": plan["node"], "source": source(plan["config"])}), 0o600, host.admin_uid, os.getegid())
        _sync(host.path(ROOT))
    directory(INPUTS, 0o700)
    directory("/usr/local/libexec", 0o755)
    directory(LIBEXEC, 0o755)
    for name, text in plan["files"].items():
        if state["files"][name] and state["files"][name]["text"] == text:
            continue
        path = host.path(name)
        temporary = path.parent / (".ml-nfs-client-" + uuid.uuid4().hex)
        try:
            _write_new(temporary, text.encode(), 0o644, host.admin_uid, os.getegid())
            if host.read(name, mounts) != state["files"][name]:
                raise SetupError("Client config changed before publication; preserve it: " + name)
            if state["files"][name] is None:
                os.link(temporary, path, follow_symlinks=False)
            else:
                os.replace(temporary, path)
            _sync(path.parent)
        finally:
            temporary.unlink(missing_ok=True)
    return {"status": "configuration_staged_not_activated", "backup": str(backup), "activated": False}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", type=Path, default=CONFIG_FILE)
    parser.add_argument("--node", choices=("pi01", "pi02", "pi03"))
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--dry-run", action="store_true", help="Offline preview for selected Pis (all three by default)")
    mode.add_argument("--inspect-local", action="store_true", help="Read-only inspection on the selected Pi")
    mode.add_argument("--apply", action="store_true", help="Future approved root-only config staging, no activation")
    mode.add_argument("--install-missing-package", action="store_true", help="Future separately approved root-only offline package provisioning")
    parser.add_argument("--reviewed-plan-sha256")
    args = parser.parse_args(argv)
    try:
        config = load_config(args.config)
        local = args.inspect_local or args.apply or args.install_missing_package
        if local and not args.node:
            raise SetupError("Local inspection/actions require an explicit --node")
        if not local and args.node:
            raise SetupError("Offline preview covers the configured deployment nodes; omit --node")
        if args.apply or args.install_missing_package:
            if not args.reviewed_plan_sha256:
                raise SetupError("Live action requires a current reviewed digest and prior explicit approval")
            action = stage_configuration if args.apply else provision_package
            result = action(config, args.node, args.reviewed_plan_sha256)
        else:
            if args.reviewed_plan_sha256:
                raise SetupError("Review digest is only used for approved live actions")
            result = inspect_local(config, args.node) if local else plan_all(config)
        print(json.dumps(result, indent=2, sort_keys=True))
        return 2 if result.get("blockers") else 0
    except (SetupError, OSError, ValueError, subprocess.SubprocessError) as error:
        parser.exit(2, "NFS client setup refused: " + str(error) + "\n")


if __name__ == "__main__":
    raise SystemExit(main())

nfs_mount.py.source:
"""Read-only NFS mount admission check, also installable as a standalone guard.

This reads kernel metadata only: it never looks up a file in the mount, triggers
an automount, stages inputs or authorizes/launches training. The future trusted
stager must use the check in its own mount namespace before accessing inputs.
"""

import argparse
import ipaddress
import json
from pathlib import Path
import re

INPUTS = "/srv/mlnfs/inputs"
EXPORT = "/srv/ml-shared/objects"
REQUIRED = {"ro", "nosuid", "nodev", "noexec", "hard", "proto=tcp", "sec=sys", "vers=4.1"}
FORBIDDEN = {"rw", "soft", "softerr", "softreval", "suid", "dev", "exec", "user", "users"}


class MountNotReady(ValueError):
    """The visible mount metadata does not meet the reviewed input contract."""


def unescape(value):
    return re.sub(r"\\([0-7]{3})", lambda match: chr(int(match[1], 8)), value)


def parse_mountinfo(text):
    mounts = []
    for line in text.splitlines():
        if not line:
            continue
        try:
            left, right = line.split(" - ", 1)
            a, b = left.split(), right.split()
            mounts.append({"id": int(a[0]), "parent": int(a[1]), "device": a[2],
                           "root": unescape(a[3]), "target": unescape(a[4]),
                           "vfs_options": a[5].split(","), "fstype": b[0],
                           "source": unescape(b[1]), "fs_options": b[2].split(",")})
        except (ValueError, IndexError) as error:
            raise MountNotReady("Malformed kernel mount metadata") from error
    return mounts


def validate_source(source):
    try:
        host, path = source.split(":", 1)
        ip = ipaddress.IPv4Address(host)
    except (ValueError, AttributeError) as error:
        raise MountNotReady("Expected a literal IPv4 controller and fixed input export") from error
    if path != EXPORT or ip.is_loopback or ip.is_multicast or ip.is_unspecified or ip.is_reserved or ip.is_link_local:
        raise MountNotReady("Unsafe controller input source")
    return str(ip) + ":" + EXPORT


def require_input_mount(source, mountinfo=None):
    source = validate_source(source)
    text = Path("/proc/self/mountinfo").read_text() if mountinfo is None else mountinfo
    mounts = parse_mountinfo(text)
    exact = [m for m in mounts if m["target"] == INPUTS]
    nfs = [m for m in exact if m["fstype"] in ("nfs", "nfs4")]
    if len(nfs) != 1 or any(m["fstype"] not in ("autofs", "nfs", "nfs4") for m in exact) or len(exact) > 2:
        raise MountNotReady("Exact input NFS mount absent or shadowed; an ordinary directory/autofs is not ready")
    mount = nfs[0]
    if mount["source"] != source or mount["root"] != "/":
        raise MountNotReady("Wrong input source or bind-subdirectory mount")
    by_id = {item["id"]: item for item in mounts}
    if len(by_id) != len(mounts):
        raise MountNotReady("Duplicate kernel mount identity")
    ancestors = set()
    current = mount
    while current is not None:
        if current["id"] in ancestors:
            raise MountNotReady("Cyclic kernel mount ancestry")
        ancestors.add(current["id"])
        current = by_id.get(current["parent"])
    for item in mounts:
        target = item["target"]
        if target != INPUTS and (target == "/" or INPUTS.startswith(target.rstrip("/") + "/")) and item["id"] not in ancestors:
            raise MountNotReady("Input mount hidden by an ancestor overmount")
    vfs = set(mount["vfs_options"])
    values = vfs | set(mount["fs_options"])
    # Linux may report an rw NFS superblock beneath a read-only mount. Access
    # restrictions are per-mount VFS flags; server export policy is checked
    # separately. Never accept rw (or missing security flags) in the VFS field.
    if not REQUIRED <= values or values & (FORBIDDEN - {"rw"}) or "rw" in vfs or not {"ro", "nosuid", "nodev", "noexec"} <= vfs:
        raise MountNotReady("Input mount lacks required read-only/security/protocol options")
    if any(m["target"].startswith(INPUTS + "/") for m in mounts):
        raise MountNotReady("Unexpected nested mount inside input tree")
    return {"ready": True, "mount_id": mount["id"], "source": source, "target": INPUTS,
            "version": "4.1", "scope": "Metadata admission only; not server liveness, authorization or byte verification"}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", required=True)
    args = parser.parse_args(argv)
    try:
        print(json.dumps(require_input_mount(args.source), sort_keys=True))
        return 0
    except (MountNotReady, OSError) as error:
        print(json.dumps({"ready": False, "error": str(error)}, sort_keys=True))
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
